namespace CloudServer; public partial class App : System.Windows.Application { protected override void OnStartup(System.Windows.StartupEventArgs e){base.OnStartup(e);var store=new StateStore();if(store.State.Users.Count==0){var setup=new FirstRunWindow();if(setup.ShowDialog()!=true){Shutdown();return;}store.State.Users.Add(new UserAccount{UserName=setup.UserName,DisplayName=setup.DisplayName,IsAdmin=true,PasswordHash=StateStore.Hash(setup.Password),QuotaBytes=0});store.Save();}var admin=new AdminWindow(store);admin.Show();System.Threading.Tasks.Task.Run(()=>Api.Run(store)).ContinueWith(t=>Dispatcher.Invoke(()=>admin.SetApiStatus(t.Exception?.GetBaseException())),System.Threading.Tasks.TaskScheduler.Default);} }